import sys


def main():
    n = int(sys.stdin.read().split()[0])

    a = [[0] * n for _ in range(n)]
    for i in range(n):
        a[i][0] = 1
        a[i][i] = 1
    for i in range(2, n):
        for j in range(1, i):
            a[i][j] = a[i - 1][j - 1] + a[i - 1][j]

    lines = []
    for i in range(n):
        lines.append("".join(f"{a[i][j]:5d}" for j in range(i + 1)))
    print("\n".join(lines))


if __name__ == "__main__":
    main()

