import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))
    key = int(data[1 + n])

    low, high = 0, n - 1
    pos = -1
    while low <= high:
        mid = low + (high - low) // 2
        if a[mid] == key:
            pos = mid
            break
        elif a[mid] < key:
            low = mid + 1
        else:
            high = mid - 1

    print(pos)


if __name__ == "__main__":
    main()

